-- Windows system process name running from the wrong folder
-- 405b12ce-4eab-42ab-b884-2034c40f2317
SELECT uid, time, hostname, product, user_name, process_name, process_path, cmd_line, parent_path, target_file, dst_ip, dst_port FROM ocsf_flat WHERE time >= ? AND time < ? AND class_uid = 1007 AND activity_id = 1 AND ((coalesce(process_path ILIKE '%\\lsass.exe' ESCAPE '\', false) OR coalesce(process_path ILIKE '%\\svchost.exe' ESCAPE '\', false) OR coalesce(process_path ILIKE '%\\csrss.exe' ESCAPE '\', false) OR coalesce(process_path ILIKE '%\\smss.exe' ESCAPE '\', false) OR coalesce(process_path ILIKE '%\\wininit.exe' ESCAPE '\', false) OR coalesce(process_path ILIKE '%\\winlogon.exe' ESCAPE '\', false) OR coalesce(process_path ILIKE '%\\services.exe' ESCAPE '\', false) OR coalesce(process_path ILIKE '%\\lsm.exe' ESCAPE '\', false)) AND NOT (coalesce(process_path ILIKE 'C:\\Windows\\System32\\%' ESCAPE '\', false) OR coalesce(process_path ILIKE 'C:\\Windows\\SysWOW64\\%' ESCAPE '\', false) OR coalesce(process_path ILIKE 'C:\\Windows\\WinSxS\\%' ESCAPE '\', false))) ORDER BY time;
